const townDictionary=[...new Map([...TownTranslations,...Object.entries(InterfaceEnglish)])].sort((a,b)=>b[0].length-a[0].length);
for(const[zh,en]of townDictionary)TownLocale.register(zh,en);
const translatedCourses=new Set();
function registerCourseLanguage(){const c=currentCourse();if(!c||translatedCourses.has(c.id))return;translatedCourses.add(c.id);TownLocale.registerObject(c);function add(base,en){if(typeof base==='string'&&typeof en==='string'&&base&&en&&base!==en){townDictionary.push([base,en]);TownLocale.register(base,en);}else if(Array.isArray(base)&&Array.isArray(en))base.forEach((v,i)=>add(v,en[i]));else if(base&&en&&typeof base==='object'&&typeof en==='object')for(const key of ['q','a','wrong','answers','steps','pairs','left','right','blank','context','title','body','example','quote','category','boundary'])if(key in base)add(base[key],en[key]);}for(const ch of c.chapters){add(ch.title,ch.english);for(const sec of ch.sections){add(sec.title,sec.english);for(const l of sec.lessons)add(l,l.en);for(const q of sec.questions||[])add(q,q.en);}}townDictionary.sort((a,b)=>b[0].length-a[0].length);}
function translateTownText(text){let s=text;for(const[from,to]of townDictionary)if(from&&s.includes(from)){if(from.length===1){if(s.trim()===from)s=s.replace(from,to);}else s=s.split(from).join(to);}return s.replace(/第\s*(\d+(?:\/\d+)?)\s*章/g,'Chapter $1').replace(/(\d+)\s*个小节/g,'$1 sections').replace(/任务\s*(\d+)/g,'Task $1').replace(/整理背包中\s*(\d+)\s*份/g,'File $1 collected items').replace(/为「([^」]+)」/g,'For $1, ').replace(/[「」]/g,'').replace(/；/g,'; ').replace(/：/g,': ').replace(/查看(?=[A-Za-z])/g,'Inspect ').replace(/打开(?=[A-Za-z])/g,'Open ').replace(/与(?=[A-Za-z])/g,'Talk to ').replace(/([A-Za-z])与/g,'$1 and ').replace(/对话，/g,': ');}
let languageView=null;
function languageButtonLabels(){for(const id of ['languageToggle','awayLanguageToggle','dialogLanguageToggle']){const button=$(id);if(!button)continue;const label={zh:'中文 ▾',en:'English ▾',bi:'中英双语 ▾'}[TownLocale.mode(state.language)];button.dataset.localeFixed='true';button.ariaLabel=state.language==='en'?'Choose Chinese, English or bilingual display':'选择中文、英文或中英双语';if(button.textContent!==label)button.textContent=label;}}
function applyTownLanguage(){registerCourseLanguage();languageButtonLabels();if(!document.createTreeWalker)return;const mode=TownLocale.mode(state.language);document.documentElement.lang=mode==='en'?'en':'zh-CN';document.documentElement.dataset.localeMode=mode;
 // Only generated text wrappers are replaced; buttons, inputs and their event handlers stay intact.
 if(mode!=='bi')document.querySelectorAll('[data-town-pair]').forEach(wrapper=>{const pair=wrapper._townPair;if(!pair||!wrapper.parentNode)return;const node=document.createTextNode(pair[mode]);node._townPair=pair;node._townRendered=node.nodeValue;wrapper.parentNode.replaceChild(node,wrapper);});
 const walker=document.createTreeWalker(document.body,4),nodes=[];let node;while(node=walker.nextNode())nodes.push(node);
 for(const node of nodes){const parent=node.parentElement;if(!parent||['SCRIPT','STYLE','TEXTAREA'].includes(parent.tagName)||parent.closest('[data-town-pair], [data-locale-fixed], [translate="no"], [contenteditable],input'))continue;const pair=node._townRendered===node.nodeValue?node._townPair:TownLocale.pair(node.nodeValue,translateTownText);if(!pair)continue;
 if(mode==='bi'&&pair.zh!==pair.en&&!['OPTION','TITLE'].includes(parent.tagName)){const wrapper=document.createElement('span');wrapper.className='town-language-pair';wrapper.dataset.townPair='true';wrapper._townPair=pair;const zh=document.createElement('span'),en=document.createElement('span');zh.lang='zh-CN';en.lang='en';en.className='town-language-secondary';zh.textContent=pair.zh;en.textContent=pair.en;wrapper.appendChild(zh);wrapper.appendChild(en);node.parentNode.replaceChild(wrapper,node);}else{const next=mode==='bi'?pair.zh+' / '+pair.en:pair[mode];node._townPair=pair;node._townRendered=next;if(node.nodeValue!==next)node.nodeValue=next;}}
 document.querySelectorAll('[title], [aria-label], [placeholder], [alt]').forEach(el=>{if(el.closest('[data-locale-fixed], [translate="no"]'))return;for(const key of ['title','aria-label','placeholder','alt']){const value=el.getAttribute(key);if(value===null)continue;el._townAttrs??={};let pair=el._townAttrs[key];if(!pair||![pair.zh,pair.en,pair.bi].includes(value)){pair=TownLocale.pair(value,translateTownText);if(!pair)continue;pair={...pair,bi:pair.zh+' / '+pair.en};el._townAttrs[key]=pair;}if(value!==pair[mode])el.setAttribute(key,pair[mode]);}});
}
function showTownLanguagePicker(){if($('townLanguagePicker')){$('townLanguagePicker').remove();return;}const panel=document.createElement('div');panel.id='townLanguagePicker';panel.className='town-language-picker';panel.dataset.localeFixed='true';panel.innerHTML=`<strong>显示语言 · Display language</strong>${[['zh','中文'],['en','English'],['bi','中英双语 · Chinese + English']].map(([key,label])=>`<button id="language-${key}" data-town-language="${key}" aria-pressed="${TownLocale.mode(state.language)===key}">${label}</button>`).join('')}<button id="languagePickerCancel">关闭 · Close</button>`;($('dialog').open?$('dialog'):document.body).appendChild(panel);document.querySelectorAll('[data-town-language]').forEach(button=>button.onclick=()=>changeTownLanguage(button.dataset.townLanguage));$('languagePickerCancel').onclick=()=>panel.remove();}
function changeTownLanguage(mode){mode=mode===undefined?{zh:'en',en:'bi',bi:'zh'}[TownLocale.mode(state.language)]:TownLocale.mode(mode);$('townLanguagePicker')?.remove();state.language=mode;save();
 // Translate the live DOM: reopening a view resets selections, focus and transient feedback.
 // Text pairs and attributes are reversible; inputs, IDs and handlers remain the same nodes.
 applyTownLanguage();}
$('languageToggle').onclick=showTownLanguagePicker;
const languageAway=openAwayScene;
openAwayScene=function(id,message=''){languageAway(id,message);if(!activeAwayScene)return;const el=document.createElement('button');el.id='awayLanguageToggle';el.textContent='显示语言';el.onclick=showTownLanguagePicker;($('awayScene').querySelector?.('.away-switches')||$('awayScene')).appendChild(el);applyTownLanguage();};
if(typeof MutationObserver!=='undefined'){let pending=false;new MutationObserver(()=>{if(pending)return;pending=true;queueMicrotask(()=>{pending=false;applyTownLanguage();});}).observe(document.body,{childList:true,subtree:true,characterData:true});}
